-- AT Protocol label storage (issue #33).
-- Materialized index of applied labels ingested from
-- com.atproto.label.subscribeLabels (#labels frames). Labels are free-standing
-- data objects, not domain entities — this table is the storage half of the
-- label primitive; the labeler service (#34) builds on top of it later.
-- Generated by codegraph. DO NOT EDIT.

CREATE SCHEMA IF NOT EXISTS atproto;

CREATE TABLE atproto.label (
    seq BIGINT PRIMARY KEY,
    src_did TEXT NOT NULL,
    uri TEXT NOT NULL,
    cid TEXT,
    val TEXT NOT NULL,
    neg BOOLEAN NOT NULL DEFAULT false,
    cts TIMESTAMPTZ NOT NULL,
    exp TIMESTAMPTZ,
    sig BYTEA,
    verified BOOLEAN NOT NULL DEFAULT false,
    raw_event JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    platform_organization_id UUID NOT NULL
        DEFAULT '00000000-0000-0000-0000-000000000000'::uuid
);

CREATE INDEX idx_atproto_label_src_uri ON atproto.label (src_did, uri);
CREATE INDEX idx_atproto_label_uri_val ON atproto.label (uri, val);

-- ============================================================================
-- Row-Level Security policies
-- ============================================================================
--
-- Uses get_current_org_id() which reads app.organization_id session var,
-- set by the Axum middleware for BOTH API key and JWT auth, so one policy set
-- works for all auth modes. Labels are platform-wide data (the firehose
-- ingestor writes them as the app role); the zero-UUID sentinel keeps them
-- visible to every org while still allowing org-scoped inserts.

ALTER TABLE atproto.label ENABLE ROW LEVEL SECURITY;
ALTER TABLE atproto.label FORCE ROW LEVEL SECURITY;

-- Drop all existing policies (clean slate on regeneration)
DO $$ DECLARE pol RECORD; BEGIN
  FOR pol IN SELECT policyname FROM pg_policies
    WHERE schemaname = 'atproto' AND tablename = 'label'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON atproto.label', pol.policyname);
  END LOOP;
END $$;

-- Org isolation: SELECT
CREATE POLICY "org_isolation_select" ON atproto.label
  FOR SELECT
  USING ((platform_organization_id = public.get_current_org_id()
    OR platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid));

-- Org isolation: INSERT
CREATE POLICY "org_isolation_insert" ON atproto.label
  FOR INSERT
  WITH CHECK ((platform_organization_id = public.get_current_org_id()
    OR platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid));

-- Org isolation: UPDATE
CREATE POLICY "org_isolation_update" ON atproto.label
  FOR UPDATE
  USING ((platform_organization_id = public.get_current_org_id()
    OR platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid))
  WITH CHECK ((platform_organization_id = public.get_current_org_id()
    OR platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid));

-- Org isolation: DELETE
CREATE POLICY "org_isolation_delete" ON atproto.label
  FOR DELETE
  USING ((platform_organization_id = public.get_current_org_id()
    OR platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid));

-- API key scope-aware policies
CREATE POLICY "api_key_scoped_select" ON atproto.label
  FOR SELECT TO api_key
  USING (
    public.get_api_key_org_id() IS NOT NULL
    AND ((platform_organization_id IS NULL OR platform_organization_id = public.get_api_key_org_id()))
    AND public.check_api_key_scope('label', seq::text, 'read')
  );

CREATE POLICY "api_key_scoped_insert" ON atproto.label
  FOR INSERT TO api_key
  WITH CHECK (
    public.get_api_key_org_id() IS NOT NULL
    AND ((platform_organization_id IS NULL OR platform_organization_id = public.get_api_key_org_id()))
    AND public.check_api_key_scope('label', '*', 'create')
  );

CREATE POLICY "api_key_scoped_update" ON atproto.label
  FOR UPDATE TO api_key
  USING (
    public.get_api_key_org_id() IS NOT NULL
    AND ((platform_organization_id IS NULL OR platform_organization_id = public.get_api_key_org_id()))
    AND public.check_api_key_scope('label', seq::text, 'update')
  )
  WITH CHECK (
    public.get_api_key_org_id() IS NOT NULL
    AND ((platform_organization_id IS NULL OR platform_organization_id = public.get_api_key_org_id()))
    AND public.check_api_key_scope('label', seq::text, 'update')
  );

CREATE POLICY "api_key_scoped_delete" ON atproto.label
  FOR DELETE TO api_key
  USING (
    public.get_api_key_org_id() IS NOT NULL
    AND ((platform_organization_id IS NULL OR platform_organization_id = public.get_api_key_org_id()))
    AND public.check_api_key_scope('label', seq::text, 'delete')
  );

-- Schema + table privileges for app_user and api_key (RLS policies only
-- filter rows; these grants enable access). Idempotent.
GRANT USAGE ON SCHEMA atproto TO app_user, api_key;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA atproto TO app_user, api_key;
ALTER DEFAULT PRIVILEGES IN SCHEMA atproto
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user, api_key;
